SELECT 
FROM CLOUDWALK.CROWD_STATISTICS 
WHERE DEVICE_CODE = #{deviceCode} 
AND RECORD_TIME BETWEEN #{startTime} AND #{endTime}
ORDER BY RECORD_TIME DESC

SELECT AVG(COUNT) 
FROM CLOUDWALK.CROWD_STATISTICS 
WHERE DEVICE_CODE = #{deviceCode} 
AND RECORD_TIME BETWEEN #{startTime} AND #{endTime}

SELECT MAX(COUNT) 
FROM CLOUDWALK.CROWD_STATISTICS 
WHERE DEVICE_CODE = #{deviceCode} 
AND RECORD_TIME BETWEEN #{startTime} AND #{endTime}

SELECT 
FROM CLOUDWALK.CROWD_STATISTICS 
WHERE DEVICE_CODE = #{deviceCode} 
AND COUNT > #{threshold}
AND RECORD_TIME BETWEEN #{startTime} AND #{endTime}
ORDER BY COUNT DESC

SELECT DENSITY 
FROM CLOUDWALK.CROWD_STATISTICS 
WHERE DEVICE_CODE = #{deviceCode} 
AND RECORD_TIME = #{time}

SELECT 
FROM CLOUDWALK.CROWD_STATISTICS 
WHERE DEVICE_CODE = #{deviceCode} 
AND RECORD_TIME BETWEEN #{startTime} AND #{endTime}
ORDER BY RECORD_TIME ASC

SELECT AVG(DENSITY) 
FROM CLOUDWALK.CROWD_STATISTICS 
WHERE DEVICE_CODE = #{deviceCode} 
AND RECORD_TIME BETWEEN #{startTime} AND #{endTime}

SELECT * FROM CLOUDWALK.CROWD_STATISTICS

    
        AND TOURISM_NAME = #{tourismName}
    
    
        AND DEVICE_CODE = #{deviceCode}
    
    
        AND ALG_NAME = #{algName}
    
    
        AND RECORD_TIME >= #{startTime}
    
    
        AND RECORD_TIME <= #{endTime}
    

ORDER BY RECORD_TIME DESC

SELECT * FROM CLOUDWALK.CROWD_STATISTICS
WHERE DEVICE_CODE = #{deviceCode}
AND ALG_NAME = #{algName}
AND RECORD_TIME BETWEEN #{recordBeginDate} AND #{recordEndDate}
ORDER BY RECORD_TIME DESC
